        "icon": "../assets/r_004472_01_2_geo-alt.svg"
      },
      {
        "dayDate": "Apr 11",
        "area": "Arashiyama",
        "morningActivity": "Tenryu-ji & Bamboo Grove",
        "afternoonActivity": "Riverside walk & Okochi Sanso",
        "dinnerSuggestion": "Central Kyoto",
        "spend": "JPY 24,000",
        "icon": "../assets/r_004472_01_3_tree.svg"
      },
      {
        "dayDate": "Apr 12",
        "area": "Northern Kyoto",
        "morningActivity": "Kinkaku-ji",
        "afternoonActivity": "Ryoan-ji",
        "dinnerSuggestion": "Downtown Kyoto",
        "spend": "JPY 20,000"
      },
      {
        "dayDate": "Apr 13",
        "area": "Nara",
        "morningActivity": "Todai-ji",
        "afternoonActivity": "Nara Park & Isuien Garden",
        "dinnerSuggestion": "Kyoto",
        "spend": "JPY 28,000",
        "icon": "../assets/r_004482_01_4_signpost-split.svg",
        "image": "../assets/r_004482_01_5_DeerNaraJapan.jpg",
        "imageAlt": "Deer in Nara Park"
      },
      {
        "dayDate": "Apr 14",
        "area": "Fushimi / Central",
        "morningActivity": "Fushimi Inari Taisha",
        "afternoonActivity": "Sake district or food tour",
        "dinnerSuggestion": "Kyoto Station splurge",
        "spend": "JPY 26,000",
        "icon": "../assets/r_004473_01_3_cup-hot.svg"
      }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "summary", "itineraryTable", "actions"]
    },
    "title": {
      "type": "Text",
      "props": { "text": "Kyoto Spring Travel Plan: 2026-04-10 to 2026-04-14", "variant": "h1" }
    },
    "summary": {
      "type": "Text",
      "props": { "text": "A 5-day plan for 2 adults with a JPY 180,000 budget, focusing on temples, gardens, and efficient transit." }
    },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "statePath": "/itinerary",
        "columns": [
          { "key": "dayDate", "label": "Date" },
          { "key": "area", "label": "Area" },
          { "key": "morningActivity", "label": "Morning" },
          { "key": "afternoonActivity", "label": "Afternoon" },
          { "key": "dinnerSuggestion", "label": "Dinner" },
          { "key": "spend", "label": "Spend" }
        ]
      }
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Kyoto Transit Map", "openUrl": "https://www.jr-odekake.net/railroad/en/" } },
    "btn2": { "type": "Button", "props": { "label": "Kyoto Official Travel", "openUrl": "https://www.kyoto.travel/en" } },
    "btn3": { "type": "Button", "props": { "label": "Nara Official Guide", "openUrl": "https://www.visitnara.jp/en/" } }
  }
}
